<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';require __DIR__.'/_auth.php';$admin=saas_require();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$tenant=(int)($_POST['tenant_id']??0);$action=$_POST['action']??'';if(in_array($action,['activate','suspend'],true)){db()->beginTransaction();$status=$action==='activate'?'active':'suspended';db()->prepare("UPDATE tenants SET status=:s,updated_at=NOW() WHERE id=:id")->execute(['s'=>$status,'id'=>$tenant]);db()->prepare("UPDATE subscriptions SET status=:s,updated_at=NOW() WHERE tenant_id=:id ORDER BY id DESC LIMIT 1")->execute(['s'=>$status,'id'=>$tenant]);db()->commit();}elseif($action==='plan'){$plan=(int)($_POST['plan_id']??0);$ck=db()->prepare("SELECT id FROM plans WHERE id=:p AND active=1 LIMIT 1");$ck->execute(['p'=>$plan]);if($ck->fetchColumn()){db()->prepare("UPDATE subscriptions SET plan_id=:p,updated_at=NOW() WHERE tenant_id=:t ORDER BY id DESC LIMIT 1")->execute(['p'=>$plan,'t'=>$tenant]);}}elseif($action==='renew'){db()->prepare("UPDATE subscriptions SET status='active',current_period_start=CURDATE(),current_period_end=DATE_ADD(CURDATE(),INTERVAL 1 MONTH),updated_at=NOW() WHERE tenant_id=:t ORDER BY id DESC LIMIT 1")->execute(['t'=>$tenant]);db()->prepare("UPDATE tenants SET status='active',updated_at=NOW() WHERE id=:t")->execute(['t'=>$tenant]);}redirect('saas/index.php');}$stats=db()->query("SELECT (SELECT COUNT(*) FROM tenants) tenants,(SELECT COUNT(*) FROM subscriptions WHERE status='active') active,(SELECT COUNT(*) FROM subscriptions WHERE status='suspended') suspended,(SELECT COALESCE(SUM(p.price_monthly),0) FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.status='active') mrr")->fetch();$rows=db()->query("SELECT t.id,t.name,t.slug,t.email,t.status,s.current_period_end,s.status subscription_status,p.id plan_id,p.name plan_name,p.price_monthly,(SELECT COUNT(*) FROM users u WHERE u.tenant_id=t.id AND u.active=1) user_count,(SELECT COUNT(*) FROM patients x WHERE x.tenant_id=t.id AND x.status='active') patient_count FROM tenants t LEFT JOIN subscriptions s ON s.id=(SELECT s2.id FROM subscriptions s2 WHERE s2.tenant_id=t.id ORDER BY s2.id DESC LIMIT 1) LEFT JOIN plans p ON p.id=s.plan_id ORDER BY t.created_at DESC LIMIT 100")->fetchAll();$plans=db()->query("SELECT id,name FROM plans WHERE active=1 ORDER BY price_monthly")->fetchAll();layout('Painel SaaS',function()use($admin,$stats,$rows,$plans){?><div class="content" style="max-width:1400px"><div class="page-head"><div><a class="brand" href="<?=e(url('saas/index.php'))?>"><span class="brand-mark">P</span><span>PsicoManager <b>AI</b> · SaaS</span></a><h1 style="margin-top:25px">Administração comercial</h1><p>Olá, <?=e($admin['name'])?>. Esta área administra tenants e assinaturas, sem abrir prontuários.</p></div><a class="button ghost" href="<?=e(url('saas/logout.php'))?>">Sair</a></div><div class="kpi-grid"><div class="kpi"><small>Clientes</small><strong><?=$stats['tenants']?></strong></div><div class="kpi"><small>Ativos</small><strong><?=$stats['active']?></strong></div><div class="kpi"><small>Suspensos</small><strong><?=$stats['suspended']?></strong></div><div class="kpi"><small>MRR estimado</small><strong>R$ <?=number_format((float)$stats['mrr'],2,',','.')?></strong></div></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Cliente</th><th>Plano</th><th>Uso</th><th>Período</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><small><?=e($r['slug'])?> · <?=e($r['email'])?></small></td><td><form method="post" class="split-actions"><?=csrf_field()?><input type="hidden" name="action" value="plan"><input type="hidden" name="tenant_id" value="<?=$r['id']?>"><select name="plan_id"><?php foreach($plans as $p):?><option value="<?=$p['id']?>" <?=$r['plan_id']==$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach?></select><button class="button ghost small">Trocar</button></form></td><td><?=$r['user_count']?> usuários<br><?=$r['patient_count']?> pacientes</td><td><?=e($r['current_period_end']?date('d/m/Y',strtotime($r['current_period_end'])):'—')?></td><td><span class="status <?=e($r['subscription_status']??$r['status'])?>"><?=e($r['subscription_status']??$r['status'])?></span></td><td><form method="post" class="split-actions"><?=csrf_field()?><input type="hidden" name="tenant_id" value="<?=$r['id']?>"><button class="button ghost small" name="action" value="renew">Renovar 1 mês</button><?php if($r['status']==='active'):?><button class="button ghost small" name="action" value="suspend">Suspender</button><?php else:?><button class="button small" name="action" value="activate">Ativar</button><?php endif?></form></td></tr><?php endforeach?></tbody></table></div></section></div><?php },['public'=>true]);
